// Original bilingual Senior 1 micro-inquiries. Diagrams support observation;
// the authored justifications, not a finite sweep of sliders, establish claims.
export const bi=(en,zh)=>({en,'zh-Hant':zh});
const B=x=>Array.isArray(x)?bi(...x):x;
const pick=(x,locale)=>typeof x==='object'&&x!==null?(x[locale]??x.en):String(x);
const n=(p,k,d)=>Number.isFinite(Number(p[k]))?Number(p[k]):d;
const rad=x=>x*Math.PI/180, near=(a,b=0)=>Math.abs(a-b)<1e-9;
const f=x=>Number.isFinite(x)?String(Number(x.toFixed(5))):'—';
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numeric=(key,en,zh,min,max,step=1)=>({key,label:bi(en,zh),min,max,step});
const select=(key,en,zh,items)=>({key,label:bi(en,zh),options:items.map(([value,e,z])=>({value,label:bi(e,z)}))});
const scenario=(en,zh,params,boundary=false)=>({label:bi(en,zh),params,boundary});
const prereq={
 '07':bi('Angles, coordinates and basic function graphs.','角、坐標及基本函數圖像。'),
 '08':bi('Coordinates, displacement and Pythagoras.','坐標、位移及勾股定理。'),
 '09':bi('Triangle angles, sine and cosine.','三角形內角、正弦及餘弦。'),
 '10':bi('Plane area, Pythagoras and units.','平面面積、勾股定理及單位。'),
 '14':bi('Points, lines, planes and vector directions.','點、直線、平面及向量方向。'),
};
function make(chapter,order,s){return {id:`g10-${chapter}-${String(order).padStart(2,'0')}`,chapter,order,title:B(s.title),question:B(s.q),prediction:B(s.predict),prerequisites:prereq[chapter],explanation:B(s.explain),conditions:B(s.conditions),misconception:B(s.mistake),proof:B(s.proof),teacherPrompt:B(s.ask),challenge:B(s.challenge),exit:{prompt:B(s.exit),answer:B(s.answer)},cases:s.cases,controls:s.controls};}
